begin;
create extension if not exists pgtap with schema extensions;
select plan(12);
set local role authenticated;
set local request.jwt.claims = '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}';
select throws_ok($$select 1 from public.egg_ai_interest_poll_sessions$$,'42501',null,'first user cannot read AI sessions');
select throws_ok($$update public.egg_ai_interest_poll_sessions set session_hash=repeat('f',64) returning 1$$,'42501',null,'first user cannot change sessions');
select throws_ok($$delete from public.egg_ai_interest_poll_sessions returning 1$$,'42501',null,'first user cannot delete sessions');
select throws_ok($$insert into public.egg_ai_interest_poll_sessions(campaign_id,session_hash,poll_id) values(1,repeat('f',64),1)$$,'42501',null,'first user cannot forge a session');
select throws_ok($$select * from public.create_egg_ai_interest_poll(1,repeat('f',64),'menu','Question',array['One','Two'],true)$$,'42501',null,'first user cannot directly generate a poll');
set local request.jwt.claims = '{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}';
select throws_ok($$select 1 from public.egg_ai_interest_poll_sessions$$,'42501',null,'second user cannot read sessions');
select throws_ok($$update public.egg_ai_interest_poll_sessions set session_hash=repeat('f',64) returning 1$$,'42501',null,'second user cannot change sessions');
select throws_ok($$delete from public.egg_ai_interest_poll_sessions returning 1$$,'42501',null,'second user cannot delete sessions');
select throws_ok($$insert into public.egg_ai_interest_poll_sessions(campaign_id,session_hash,poll_id) values(1,repeat('f',64),1)$$,'42501',null,'second user cannot forge another session');
select throws_ok($$select * from public.create_egg_ai_interest_poll(1,repeat('f',64),'menu','Question',array['One','Two'],true)$$,'42501',null,'second user cannot bypass server generation');
set local request.jwt.claims = '{"role":"anon"}';
set local role anon;
select throws_ok($$select 1 from public.egg_ai_interest_poll_sessions$$,'42501',null,'anonymous visitors cannot read sessions');
select throws_ok($$select * from public.create_egg_ai_interest_poll(1,repeat('f',64),'menu','Question',array['One','Two'],true)$$,'42501',null,'anonymous visitors cannot directly generate a poll');
select * from finish();
rollback;
